/** @type {import('tailwindcss').Config} */

// Every visual value comes from app/aents-tokens.css, generated by @aents/theme
// from the Aents Brand Book. This file declares no colour, radius, shadow or
// font of its own: it only maps the token names this codebase already uses onto
// the CSS custom properties that carry them.
//
// Colours are declared twice on purpose. `--x` holds the hex, which is what most
// utilities need; `--x-rgb` holds the channel triplet, which is the only form
// Tailwind can apply an opacity modifier to. A utility written as `bg-primary/10`
// resolves through the channel variable; without it Tailwind drops the modifier
// with no build error.
const withAlpha = (channels) => `rgb(var(${channels}) / <alpha-value>)`;

