        '3xl': ['var(--type-h1-size)', { lineHeight: 'var(--type-h1-line)' }],
        '4xl': ['var(--type-h1-size)', { lineHeight: 'var(--type-h1-line)' }],
        '5xl': ['var(--type-display2-size)', { lineHeight: 'var(--type-display2-line)' }],
